# Let me analyze the patterns more systematically
inputs = ['gufwdv', 'vz', 'evifi', 'cub', 'cji']
outputs = ['gvfafwdv', 'vz', 'zevefe', 'cvfab', 'cje']

print("Input -> Output analysis:")
for i, (inp, outp) in enumerate(zip(inputs, outputs)):
    print(f"{inp} -> {outp}")

# Let's check if we can identify simple character replacements
replacements = {}
for inp, outp in zip(inputs, outputs):
    min_len = min(len(inp), len(outp))
    for j in range(min_len):
        if inp[j] != outp[j]:
            if inp[j] not in replacements:
                replacements[inp[j]] = outp[j]
            else:
                if replacements[inp[j]] != outp[j]:
                    print(f"Conflict: {inp[j]} -> {replacements[inp[j]]} vs {outp[j]}")

print("\nCharacter mappings found:", replacements)

